pub fn serialize_language_server_features(configs: Vec<LanguageServerFeatures>) -> Vec<serde_json::Value> {
    let mut result = Vec::new();
    for config in configs {
        let mut features = Vec::new();
        let mut excluded = Vec::new();

        for feature in config.only {
            features.push(feature.to_string());
        }

        for feature in config.excluded {
            excluded.push(feature.to_string());
        }

        let mut obj = serde_json::Map::new();
        obj.insert("name".to_string(), serde_json::Value::String(config.name));
        if !features.is_empty() {
            obj.insert("enabled".to_string(), serde_json::Value::Array(features));
        }
        if !excluded.is_empty() {
            obj.insert("excluded".to_string(), serde_json::Value::Array(excluded));
        }

        result.push(serde_json::Value::Object(obj));
    }

    result
}
