func (t *Terminal) setPosition(label *labelOpts, attrs string) {
	// Initialize column index to 0 and vertical position to not bottom
	label.column = 0
	label.bottom = false

	// Split the attributes string by regular expression and convert to lowercase
	tokens := splitRegexp.Split(strings.ToLower(attrs), -1)

	// Process each token
	for _, token := range tokens {
		switch token {
		case "top":
			label.bottom = false
		case "bottom":
			label.bottom = true
		default:
			// Attempt to parse the token as a column index
			if idx, err := strconv.Atoi(token); err == nil {
				label.column = idx
			}
		}
	}
}
